<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>BusinessBay Developments — Coming Soon</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Prata&family=Montserrat:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root{
    --ink:#14100C;
    --cream:#F5EBDA;
    --sand:#B7A488;
    --amber:#DCA05F;
    --red:#B0271D;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{height:100%}
  body{
    background:var(--ink);
    color:var(--cream);
    font-family:'Montserrat',sans-serif;
    overflow:hidden;
  }

  /* ---------- VIDEO BACKGROUND ---------- */
  .bg{position:fixed;inset:0;z-index:0}
  .bg video{
    width:100%;height:100%;
    object-fit:cover;
    object-position:center 30%;
  }
  .bg::after{
    content:"";
    position:absolute;inset:0;
    background:
      linear-gradient(0deg,rgba(20,16,12,.88) 0%,rgba(20,16,12,.35) 34%,rgba(20,16,12,.18) 55%,rgba(20,16,12,.45) 100%);
  }
  .bg::before{
    content:"";
    position:absolute;inset:0;z-index:1;
    background:radial-gradient(120% 90% at 50% 110%,transparent 40%,rgba(20,16,12,.55) 100%);
  }

  /* ---------- LAYOUT ---------- */
  .stage{
    position:relative;
    z-index:2;
    height:100vh;height:100dvh;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:space-between;
    text-align:center;
    padding:clamp(26px,4vh,48px) clamp(20px,4vw,48px);
  }

  .logo{width:clamp(190px,22vw,300px)}
  .logo img{width:100%;height:auto;display:block;filter:drop-shadow(0 2px 14px rgba(0,0,0,.45))}

  .center{max-width:820px;display:flex;flex-direction:column;align-items:center}

  .eyebrow{
    display:flex;align-items:center;gap:12px;
    font-size:clamp(10px,.85vw,12px);
    font-weight:700;
    letter-spacing:.46em;
    text-transform:uppercase;
    color:var(--amber);
    text-shadow:0 1px 10px rgba(0,0,0,.5);
  }
  .pulse{
    width:9px;height:9px;border-radius:50%;
    background:var(--red);position:relative;flex:0 0 auto;
  }
  .pulse::after{
    content:"";position:absolute;inset:-7px;border-radius:50%;
    border:1px solid var(--red);
    animation:ring 2.4s ease-out infinite;
  }
  @keyframes ring{0%{transform:scale(.4);opacity:.9}100%{transform:scale(1.8);opacity:0}}

  h1{
    margin-top:24px;
    font-family:'Prata',serif;
    font-weight:400;
    font-size:clamp(36px,5.4vw,76px);
    line-height:1.16;
    color:var(--cream);
    text-shadow:0 3px 26px rgba(0,0,0,.55);
  }
  h1 em{font-style:normal;color:var(--amber)}

  .rule{
    margin-top:26px;
    width:90px;height:2px;
    background:linear-gradient(90deg,transparent,var(--cream),transparent);
    position:relative;overflow:hidden;
  }
  .rule::after{
    content:"";position:absolute;inset:0;
    background:linear-gradient(90deg,transparent,rgba(220,160,95,.95),transparent);
    transform:translateX(-130%);
    animation:shimmer 3.8s ease-in-out infinite;
  }
  @keyframes shimmer{0%,55%{transform:translateX(-130%)}88%,100%{transform:translateX(230%)}}

  .lede{
    margin-top:24px;
    font-size:clamp(13px,1.05vw,16px);
    font-weight:500;
    letter-spacing:.14em;
    line-height:2;
    text-transform:uppercase;
    color:var(--sand);
    text-shadow:0 1px 10px rgba(0,0,0,.5);
  }

  .foot{
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:6px;
  }
  .hotline-label{
    font-size:10px;font-weight:600;
    letter-spacing:.44em;text-transform:uppercase;
    color:var(--sand);
  }
  .hotline-num{
    font-size:clamp(24px,2.1vw,32px);
    font-weight:700;letter-spacing:.14em;
    color:var(--cream);
    text-shadow:0 2px 14px rgba(0,0,0,.5);
  }
  .hotline-num a{color:inherit;text-decoration:none}

  /* ---------- ENTRANCE ---------- */
  .reveal{opacity:0;transform:translateY(24px);animation:rise 1.1s cubic-bezier(.22,.7,.3,1) forwards}
  .d1{animation-delay:.2s}.d2{animation-delay:.5s}.d3{animation-delay:.75s}
  .d4{animation-delay:1s}.d5{animation-delay:1.2s}.d6{animation-delay:1.45s}
  @keyframes rise{to{opacity:1;transform:none}}
  .bg{opacity:0;animation:fadein 1.8s ease forwards}
  @keyframes fadein{to{opacity:1}}

  @media (max-width:640px){
    h1{font-size:clamp(32px,9.4vw,44px)}
    .logo{width:200px}
  }
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation:none !important}
    .reveal,.bg{opacity:1;transform:none}
  }
</style>
</head>
<body>

<div class="bg" aria-hidden="true">
  <video autoplay muted loop playsinline poster="">
{{--    <source src="soon.mp4" type="video/mp4">--}}
      <source src="{{ asset('frontend/videos/coming-soon.mp4') }}" type="video/mp4">
  </video>
</div>

<main class="stage">
  <header class="logo reveal d1">
    <img src="data:image/png;base64," alt="BusinessBay Developments">
  </header>

  <section class="center">
    <div class="eyebrow reveal d2"><span class="pulse"></span> Coming Soon</div>
    <h1 class="reveal d3">Something Beautiful<br>Is <em>Rising.</em></h1>
    <div class="rule reveal d4" aria-hidden="true"></div>
    <p class="lede reveal d5">A new landmark in real estate &nbsp;·&nbsp; Where life feels elevated</p>
  </section>

  <footer class="foot reveal d6">
    <div class="hotline-label">Hotline</div>
    <div class="hotline-num"><a href="tel:16924">16924</a></div>
  </footer>
</main>

</body>
</html>
